import{_ as d,C as n,o as h,c as i,a5 as o,E as l,j as e,a as r}from"./chunks/framework.D_J2JZBr.js";const _=JSON.parse('{"title":"基础知识","description":"面向集成电路学习的数学、C 与 Python、Linux 和工程工具入门路线。","frontmatter":{"title":"基础知识","description":"面向集成电路学习的数学、C 与 Python、Linux 和工程工具入门路线。"},"headers":[],"relativePath":"learning/fundamentals/index.md","filePath":"learning/fundamentals/index.md","lastUpdated":1795531638000}'),s={name:"learning/fundamentals/index.md"};function f(b,t,g,u,c,p){const a=n("CourseTable");return h(),i("div",null,[t[0]||(t[0]=o('<h1 id="基础知识" tabindex="-1">基础知识 <a class="header-anchor" href="#基础知识" aria-label="Permalink to &quot;基础知识&quot;">​</a></h1><p>基础的作用是让后续学习不卡住，而不是增加一张必须全部刷完的清单。数字设计优先补二进制、C、命令行和时序概念；模拟与器件方向优先补微积分、线性系统和数值计算；EDA 与 AI 硬件还需要概率、矩阵和优化。先看 <a href="/shanghaitech-ic-wiki-dev.github.io/learning/">学习地图</a>，再按当前任务选择。</p><h2 id="入门-数学和编程能用起来" tabindex="-1">入门：数学和编程能用起来 <a class="header-anchor" href="#入门-数学和编程能用起来" aria-label="Permalink to &quot;入门：数学和编程能用起来&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>MIT 18.06 Linear Algebra（<a href="https://ocw.mit.edu/" target="_blank" rel="noreferrer">MIT OCW</a>）</td><td>公开课</td><td>入门</td><td>重点是线性方程组、子空间、特征值、正交投影；理解矩阵运算在表达什么</td></tr><tr><td>MIT 6.041 概率课程（<a href="https://ocw.mit.edu/" target="_blank" rel="noreferrer">MIT OCW</a>）</td><td>公开课</td><td>入门—进阶</td><td>先掌握条件概率、随机变量、期望与方差，再学随机过程</td></tr><tr><td>Oppenheim《Signals and Systems》及 MIT 相关课程</td><td>教材、公开课</td><td>入门—进阶</td><td>卷积、傅里叶变换、拉普拉斯变换与系统响应是电路和信号处理的共同语言</td></tr><tr><td>Kernighan、Ritchie《The C Programming Language》</td><td>教材</td><td>入门</td><td>配合小程序学习指针、数组、结构体、位操作；另查现代编译器与安全用法</td></tr><tr><td><a href="https://docs.python.org/" target="_blank" rel="noreferrer">Python 官方文档</a></td><td>教程、参考</td><td>入门</td><td>用于数据处理、批量实验和报告自动化，不必一开始追求复杂框架</td></tr><tr><td><a href="https://numpy.org/" target="_blank" rel="noreferrer">NumPy</a>、<a href="https://matplotlib.org/" target="_blank" rel="noreferrer">Matplotlib</a></td><td>数值与绘图库</td><td>入门</td><td>用实际数组、误差曲线和波形巩固数学概念</td></tr></tbody></table><p>一个实用练习是：用 C 实现定宽整数运算，再用 Python 生成边界输入并比较结果。注意 C 的有符号溢出、移位范围与硬件定宽截断并不自动等价。数学练习则可从离散卷积和 RC 阶跃响应开始，对照手算、数值结果与物理单位。</p><h2 id="进阶-熟悉每天都会用的工具" tabindex="-1">进阶：熟悉每天都会用的工具 <a class="header-anchor" href="#进阶-熟悉每天都会用的工具" aria-label="Permalink to &quot;进阶：熟悉每天都会用的工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://missing.csail.mit.edu/" target="_blank" rel="noreferrer">MIT Missing Semester</a></td><td>工具公开课</td><td>入门—进阶</td><td>Shell、数据整理、编辑器、Git、调试与性能分析；优先学与当前项目有关的章节</td></tr><tr><td><a href="https://www.gnu.org/software/bash/" target="_blank" rel="noreferrer">GNU Bash</a></td><td>Shell 文档</td><td>入门—进阶</td><td>掌握引号、变量、管道、重定向与退出码，读懂实验脚本</td></tr><tr><td><a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a> 与 Pro Git</td><td>官方文档、电子书</td><td>入门</td><td>从 status、diff、提交和分支开始，不把远程仓库当作临时文件同步盘</td></tr><tr><td><a href="https://www.vim.org/" target="_blank" rel="noreferrer">Vim</a> 与 <code>vimtutor</code></td><td>编辑器教程</td><td>入门</td><td>会进入编辑、保存退出、搜索替换即可开始；不必先定制复杂配置</td></tr><tr><td><a href="https://www.gnu.org/software/make/" target="_blank" rel="noreferrer">GNU Make</a></td><td>构建工具文档</td><td>进阶</td><td>用目标、依赖和配方表达构建关系，减少手动复制命令</td></tr><tr><td><a href="https://www.sourceware.org/gdb/" target="_blank" rel="noreferrer">GDB</a></td><td>调试器文档</td><td>进阶</td><td>学断点、调用栈和变量检查，替代只靠反复打印猜错误</td></tr></tbody></table><p>能在本地桌面点击运行，还不代表能在服务器复现实验。请练习从一个干净目录开始：找到输入、设置路径、运行命令、检查退出码、定位日志。使用相对路径组织项目；依赖版本和运行说明写在项目内，而不是只保存在自己的 Shell 历史中。</p><h2 id="实践-做一个可重复的小实验" tabindex="-1">实践：做一个可重复的小实验 <a class="header-anchor" href="#实践-做一个可重复的小实验" aria-label="Permalink to &quot;实践：做一个可重复的小实验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/tools/development/">EDA 环境与 Linux</a></td><td>操作指南</td><td>入门</td><td>常用命令、远程环境、作业调度及数据保密规范</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/resources">数字电路资源</a></td><td>后续路线</td><td>入门—进阶</td><td>将编程与命令行技能用到硬件仿真</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/learning/eda/resources">EDA 算法资源</a></td><td>后续路线</td><td>进阶</td><td>将矩阵、图算法和实验统计用于优化问题</td></tr></tbody></table><p>建议项目：用 Python 生成一组 RC 电路输入，分别用解析公式和数值方法求响应；保存参数、误差和曲线。用 Make 管理生成与绘图，用 Git 记录源码与参数。成功标准是其他人按说明能复现，而不是只在你的电脑上生成过一张图。</p><p>开始下一阶段前，检查自己能否解释：标准输出与标准错误的区别、相对路径从哪里算起、一个进程为何失败、矩阵每一维代表什么、数值误差是否足以改变结论。缺项可以边做边补，无需因为工具不熟而推迟所有专业课学习。</p><h2 id="与上科大课程配合" tabindex="-1">与上科大课程配合 <a class="header-anchor" href="#与上科大课程配合" aria-label="Permalink to &quot;与上科大课程配合&quot;">​</a></h2>',13)),l(a,{codes:"CS100,SI140A,EE150"}),t[1]||(t[1]=e("p",null,"这些课程提供编程、概率与信号系统基础。自学时按本校当前章节找辅助解释，不照搬外校的先修顺序或考试要求；具体安排以当学期大纲为准。",-1)),t[2]||(t[2]=e("h2",{id:"参考与来源",tabindex:"-1"},[r("参考与来源 "),e("a",{class:"header-anchor",href:"#参考与来源","aria-label":'Permalink to "参考与来源"'},"​")],-1)),t[3]||(t[3]=e("ul",null,[e("li",null,[e("a",{href:"https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm",target:"_blank",rel:"noreferrer"},"上科大信息学院 2026–2027 学年开课计划"),r("。")]),e("li",null,"通用资源的官方入口见表中链接；未附链接的教材可通过学校图书馆按书名检索。")],-1))])}const k=d(s,[["render",f]]);export{_ as __pageData,k as default};
